/*

This is frequency modulation of the very low frequency wave shape of the original demo.
I was wondering what the graphic would look like and how to code it.
A slight surprise here was the difference in the shapes of the sine
and cosine waves for this same modulation.

To actually use either waveform for audio frequency modulation
is a slight challenge since Shadertoy can only do phase modulation;
An integral of the shape would be needed. If someone has an integral equation for Wave() let me know.

You can uncomment some sound experiments in the Sound tab.

Another FM experiment:  https://www.shadertoy.com/view/X3tfR2

*/


float AA = 0.8f;
vec3 waveColor = vec3(0.4f, 0.2f, 0.8f);

float borderCircle(vec2 uv, vec2 p, float r, float border){
    float l = length(uv - p);
    float a = smoothstep(r, r - AA, l);
    r -= border;
    float a1 = smoothstep(r, r - AA, l);
    return a - a1;
}

float circle(vec2 uv, vec2 p, float r){
    float l = length(uv - p);
    float a = smoothstep(r, r - AA, l);
    return a;
}

float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    float v = length( pa - ba*h );
    v = 1.f - step(AA, v);
    return v;
}


#define PI 3.1415926535
float Wave(float time,float offset) {
    return sin( offset + time * ( 3.5 + sin(time)/time*3. ) );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord;
    uv.y = iResolution.y - uv.y;

    vec3 col = vec3(0.f);

    vec2 pos = vec2(100.f);
    float r = 50.0f; 
    vec2 p1 = vec2(pos.x + (Wave(iTime,PI/2.) * r), pos.y + (Wave(iTime,0.) * r));
    col += borderCircle(uv, pos, r, 1.f);
    col += sdSegment(uv, pos, p1);

    vec2 p2 = vec2(pos.x + r, p1.y);
    col += sdSegment(uv, p1, p2);
    if(uv.x > p2.x){
        float x = uv.x - p2.x;
        float y = Wave(iTime - (x / r),0.) * r;
        col += circle(uv, vec2(uv.x, pos.y + y), 1.f) * waveColor;
    }

    vec2 p3 = vec2(p1.x, pos.y + r);
    col += sdSegment(uv, p1, p3);
    if(uv.y > p3.y){
        float y = uv.y - p3.y;
        float x = Wave(iTime - (y / r), PI/2.) * r;
        col += circle(uv, vec2(x + pos.x, uv.y), 1.f) * waveColor;
    }

    fragColor = vec4(col,1.0);
}

#define PI 3.1415926535
float Wave(float time,float offset) {
    return sin( offset + time * ( 3.5 + sin(time)/time*3. ) );
}

#define TAU (2.*PI)
#define SIN(X) sin(mod(X,TAU))

vec2 mainSound( int samp, float time )
{

    float sig = 0.;

    //sig += SIN( time*TAU*440. ) * (.5-.5*Wave(time,0.));    // Amplitude Modulation
    //sig += SIN( time*TAU*550. ) * (.5+.5*Wave(time,PI/2.)); // Amplitude Modulation

    //sig += SIN( time*TAU*440. + 55.*Wave(time,0.) );    // Phase Modulation 
    //sig += SIN( time*TAU*550. + 55.*Wave(time,PI/2.) ); // Phase Modulation

    return vec2(.1*sig);

}
